#include <iostream>
#include <string>

int main() {
    std::string input_str;
    std::getline(std::cin, input_str);
    std::string result = "";
    bool has_at = false;
    size_t pos = 0;
    while (pos < input_str.length()) {
        if (pos != 0 && pos + 3 <= input_str.length() && input_str.substr(pos, 3) == "dot") {
            result += '.';
            pos += 2;
        } else if (pos != 0 && pos + 2 <= input_str.length() && !has_at && input_str.substr(pos, 2) == "at") {
            result += '@';
            has_at = true;
            pos += 1;
        } else {
            result += input_str[pos];
        }
        pos += 1;
    }
    std::cout << result << std::endl;
    return 0;
}
